script:
await step('Trang tải xong', async () => { await page.waitForLoadState('networkidle', { timeout: 20000 }).catch(() => {}); });
await step('Không bị chuyển về đăng nhập', async () => {
  const u = new URL(page.url());
  assert(u.hostname === 'tasks.zuizui.io', 'Đang ở ' + page.url());
  assert(!/login|account\/org/i.test(u.pathname + u.search), 'Trang yêu cầu đăng nhập lại');
});
await step('Trang có nội dung, không báo thiếu quyền', async () => {
  const t = (await page.locator('body').innerText()).trim();
  assert(t.length > 50, 'Trang gần như trống');
  assert(!/không có quyền|403/i.test(t.slice(0, 400)), 'Trang báo không có quyền');
});
